ints": [], "samples": [{"input": "5 7", "expectedOutput": "12", "explanation": "5 + 7 = 12"}], "testCases": [{"id": "tc_001", "input": "5 7", "expectedOutput": "12", "hidden": false, "weight": 20.0, "explanation": ""}, {"id": "tc_002", "input": "10 20", "expectedOutput": "30", "hidden": true, "weight": 40.0, "explanation": ""}], "evaluationSettings": {"exactOutput": true, "ignoreLeadingTrailingWhitespace": true, "ignoreLineEndingDifferences": true, "caseSensitive": true, "partialScoring": true, "allowCustomInput": true}, "explanation": ""}', 'all_or_nothing', 0.0, 'published', 'General', '', '', '2026-09-14 20:24:07', '2026-09-14 20:31:41');

